using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — knows about any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no casting needed.
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing.
//    With reflection-based options every type resolves, so this returns true:
if (webOptions.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");

// Now use options restricted to a source-generated context that only
// knows about Person.  Asking for Order will fail gracefully.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = DemoContext.Default
};

if (restrictedOptions.TryGetTypeInfo<Order>(out var orderInfo))
    Console.WriteLine($"TryGetTypeInfo<Order> succeeded → {orderInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Order> returned false — metadata not available (no exception!)");

// Models
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// Source-generated context that only includes Person.
[JsonSerializable(typeof(Person))]
internal partial class DemoContext : JsonSerializerContext;

